+
+	if (!brush) {
+		return p_brush_data;
+	}
+
+	if (is_root_shape()) {
+		return p_brush_data;
+	}
+
+	if (!painted) {
+		// Only save painted brushes.
+		return p_brush_data;
+	}
+
+	CSGBrush *n = _get_brush();
+	if (n == nullptr) {
+		return p_brush_data;
+	}
+
+	if (n->faces.size() <= 0) {
