+				}
+			}
+			invertw[i] = invrt;
+		}
+	}
+
+	n->build_from_faces(faces, uvs, smooth, materials, invert);
+
+	if (p_brush_data.has("ngons")) {
+		n->add_ngons(p_brush_data["ngons"]);
+	} else {
+		WARN_PRINT("Resource doesn't have ngon data");
+	}
+
+	if (brush) {
+		memdelete(brush);
+	}
+
+	brush = n;
+
+	dirty = false;
+}
