+
+	Transform2D p_rotation = Transform2D(angle, Vector2(0.0, 0.0));
+	for (int i = 0; i < p_faces.size(); i++) {
+		int p = p_faces[i];
+		ERR_FAIL_INDEX(p, n->faces.size());
+		for (int j = 0; j < 3; j++) {
+			n->faces.write[p].uvs[j] = p_rotation.xform(n->faces[p].uvs[j]);
+		}
+	}
+	_make_painted(true);
+}
