+	}
+
+	if (n->faces.is_empty()) {
+		return nullptr;
+	}
+
+	if (p_face > n->faces.size() || p_face < 0) {
+		return nullptr;
+	}
+
+	int mat = n->faces[p_face].material;
+	if (mat < 0) {
+		// mat can be -1
+		return nullptr;
+	}
+	return n->materials[mat];
