+		//hide collision if not root
+		p_property.usage = PROPERTY_USAGE_NO_EDITOR;
+	} else if (is_collision_prefixed && !bool(get("use_collision"))) {
+		p_property.usage = PROPERTY_USAGE_NO_EDITOR;
+	}
+}
