+void CSGShape3D::rotate_uv(const Vector<int> &p_faces, const float angle) {
+	CSGBrush *n = _get_brush();
+	ERR_FAIL_NULL_MSG(n, "Cannot get CSGBrush.");
+
+	if (n->faces.is_empty()) {
+		return;
