+int CSGShape3D::get_csg_face_smooth_group(int p_face) {
+	if (!brush) {
+		return 0;
+	}
+
+	CSGBrush *n = _get_brush();
+	if (n == nullptr) {
+		return 0;
+	}
+
+	if (n->faces.is_empty()) {
+		return 0;
+	}
+
+	if (p_face > n->faces.size() || p_face < 0) {
+		return 0;
+	}
+
